(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.2)*12 + Math.sin((x+y)*0.01+t*0.15)*8;
  const w1y = Math.cos(y*0.018-t*0.25)*18 + Math.sin(x*0.015+t*0.35)*12 + Math.cos((x-y)*0.012-t*0.18)*8;
  const w2x = Math.sin(w1x*0.025+t*0.5)*6 + Math.cos(w1y*0.02-t*0.4)*5;
  const w2y = Math.cos(w1y*0.025-t*0.45)*6 + Math.sin(w1x*0.022+t*0.55)*5;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.8],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.2],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.7],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 0.9],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 1.1],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*50, 0.11, 2.1, 0.6],
    [400+Math.cos(t*0.55+2)*60, 220+Math.sin(t*0.75)*40, 0.085, 1.8, 1.3],
    [200+Math.sin(t*0.7+1.5)*90, 10+Math.cos(t*0.3)*30, 0.075, 2.4, 0.85]
  ];
  let aS=0, iS=0, mS=0, nS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const wave = Math.sin(d*f-t*sp);
    aS += wave*w;
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    mS += Math.sin(d*f*1.3-t*sp*0.4+3.0)*w*0.6;
    nS += Math.cos(d*f*0.5+t*sp*0.8+0.7)*w*0.5;
  }
  const aN=aS/7.2, iN=iS/7.2, mN=mS/7.2, nN=nS/7.2;
  const bg1 = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const bg2 = Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const bg3 = Math.sin(sx*0.08+Math.sin(sy*0.06+t)*2+t*0.7)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const sp1=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const sp2=Math.sin(dist*0.08-ang*2+t*0.9)*Math.cos(ang*5-dist*0.03-t*0.6)*0.2;
  const sp3=Math.sin(dist*0.02+ang*6-t*2.0)*0.15;
  const spiral=sp1+sp2+sp3;
  const turb=Math.sin(sx*0.2+t*0.5)*Math.sin(sy*0.18-t*0.4)*Math.sin((sx+sy)*0.15+t*0.3)*0.3;
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const micro=Math.sin(sx*0.4+sy*0.35+t*1.5)*Math.cos(sx*0.3-sy*0.4-t*1.2)*0.12;
  const cross=Math.sin(aN*Math.PI)*Math.cos(iN*Math.PI*0.5)*0.2;
  const raw=aN-iN*0.65+mN*0.3-nN*0.2+(bg1+bg2+bg3)*0.25+spiral+cell*0.4+micro+turb*0.3+cross;
  const reaction=Math.tanh(raw*1.8);
  const reaction2=Math.tanh((raw*1.8+Math.sin(t*0.4)*0.3)*1.6);
  const blend=reaction*0.6+reaction2*0.4;
  const v=blend*0.5+0.5;
  const pal=[
    [6,12,52],[12,38,88],[18,72,115],[28,118,128],[45,155,140],
    [120,185,140],[195,200,110],[220,170,75],[215,120,65],
    [185,70,58],[140,40,62],[85,22,55],[40,15,48],[6,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const smooth=f*f*(3-2*f);
  const lum=0.82+Math.sin(blend*Math.PI)*0.18;
  const edgeR=Math.abs(blend)>0.75?1.12:1.0;
  const edgeG=Math.abs(blend)>0.6?1.06:1.0;
  const shimmer=Math.sin(sx*0.3+sy*0.25+t*3)*0.04+1;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*smooth)*lum*edgeR*shimmer)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*smooth)*lum*edgeG*shimmer)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*smooth)*lum*shimmer)|0
  ];
}
